<?php require_once __DIR__.'/config/db.php';require_once __DIR__.'/includes/functions.php';$cart=$_SESSION['cart']??[];if($_SERVER['REQUEST_METHOD']==='POST'){check_token();if(isset($_POST['remove']))unset($cart[(int)$_POST['remove']]);if(isset($_POST['qty']))foreach($_POST['qty'] as $id=>$q){$id=(int)$id;$q=max(0,min(99,(int)$q));if($q===0)unset($cart[$id]);else $cart[$id]=$q;}$_SESSION['cart']=$cart;header('Location: cart.php');exit;}$items=[];$total=0;$ids=array_filter(array_map('intval',array_keys($cart)));if($ids){$sql='SELECT id,name,base_price,stock_quantity FROM products WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).')';$s=$pdo->prepare($sql);$s->execute(array_values($ids));foreach($s->fetchAll() as $p){$p['quantity']=min((int)$cart[$p['id']],(int)$p['stock_quantity']);if($p['quantity']<1)continue;$p['line']=$p['quantity']*$p['base_price'];$total+=$p['line'];$items[]=$p;}}$pageTitle='Your bag';require __DIR__.'/includes/header.php'; ?>
<div class="container section-space"><h1 class="display-6 mb-4">Your bag</h1><?php if(!$items): ?><div class="panel text-center p-5"><h2 class="h5">Your bag is empty.</h2><a class="btn btn-dark rounded-pill mt-3" href="shop.php">Browse products</a></div><?php else: ?><form method="post" class="row g-4"><input type="hidden" name="csrf" value="<?=e(token())?>"><div class="col-lg-8"><div class="panel"><?php foreach($items as $p): ?><div class="d-flex flex-wrap align-items-center justify-content-between gap-3 py-3 border-bottom"><div><b><?=e($p['name'])?></b><div class="meta"><?=money($p['base_price'])?> each</div></div><label class="small">Qty<input class="form-control form-control-sm" type="number" min="0" max="<?=$p['stock_quantity']?>" name="qty[<?=$p['id']?>]" value="<?=$p['quantity']?>" style="width:80px"></label><b><?=money($p['line'])?></b><button class="btn btn-link text-danger btn-sm" name="remove" value="<?=$p['id']?>">Remove</button></div><?php endforeach; ?><button class="btn btn-outline-dark btn-sm mt-3" name="update" value="1">Update bag</button></div></div><div class="col-lg-4"><div class="panel"><h2 class="h5">Summary</h2><div class="d-flex justify-content-between my-3"><span>Subtotal</span><b><?=money($total)?></b></div><p class="small text-secondary">Local mock checkout only.</p><a class="btn btn-dark rounded-pill w-100" href="checkout.php">Checkout</a></div></div></form><?php endif; ?></div><?php require __DIR__.'/includes/footer.php'; ?>